const API="/api/v1"; const params=new URLSearchParams(location.search); const businessId=params.get("business_id"); let bookingToken=params.get("booking_token"); const rescheduleToken=params.get("reschedule_token"); const state={business:null,slots:[],selected:null,managed:null,confirmationResolver:null}; const $=(id)=>document.getElementById(id); const today=()=>new Intl.DateTimeFormat("en-CA",{timeZone:state.business?.timezone||"America/Sao_Paulo"}).format(new Date());
const money=(cents)=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(cents/100); const time=(value)=>new Intl.DateTimeFormat("pt-BR",{hour:"2-digit",minute:"2-digit",timeZone:state.business?.timezone||"America/Sao_Paulo"}).format(new Date(value));
const escapeHtml=(value)=>String(value).replace(/[&<>'"]/g,character=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[character]);
async function request(path,options={}){const response=await fetch(`${API}${path}`,options);const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.detail||"Não foi possível concluir.");return data}
function closeBookingConfirmation(result=false){$("booking-confirmation").hidden=true;const resolve=state.confirmationResolver;state.confirmationResolver=null;if(resolve)resolve(result)}
function confirmBookingCancellation(){$("booking-confirmation").hidden=false;setTimeout(()=>$("submit-booking-confirmation").focus(),0);return new Promise(resolve=>{state.confirmationResolver=resolve})}
function showBookingNotice(message){const notice=$("booking-notice");notice.textContent=message;notice.hidden=false;setTimeout(()=>{notice.hidden=true},3500)}
async function boot(){if(bookingToken){await loadManagedBooking();return}if(!businessId){showPageError("O link de agendamento está incompleto.");return}try{if(rescheduleToken){state.managed=await request(`/public/businesses/appointments/${rescheduleToken}`);if(!["scheduled","confirmed"].includes(state.managed.status))throw new Error("Este agendamento não pode mais ser alterado.")}state.business=await request(`/public/businesses/${businessId}`);$("business-name").textContent=state.business.name;$("service").innerHTML='<option value="">Selecione</option>'+state.business.services.map(s=>`<option value="${s.id}">${escapeHtml(s.name)} · ${s.duration_minutes} min · ${money(s.price_cents)}</option>`).join("");$("barber").innerHTML='<option value="">Selecione</option>'+state.business.barbers.map(b=>`<option value="${b.id}">${escapeHtml(b.full_name)}</option>`).join("");$("date").min=today();$("date").value=today();if(rescheduleToken){$("customer-fields").hidden=true;$("name").required=false;$("phone").required=false;$("submit").firstElementChild.textContent="Confirmar novo horário";document.querySelector(".intro>p").textContent="REAGENDAR ATENDIMENTO"}$("booking-card").hidden=false;renderSavedBookings()}catch(error){showPageError(error.message)}}
function showPageError(message){$("business-name").textContent="Agendamento indisponível";$("page-error-message").textContent=message;$("page-error").hidden=false}
async function loadSlots(){state.selected=null;state.slots=[];$("slots").innerHTML="";$("submit").disabled=true;updateSummary();const barber=$("barber").value,date=$("date").value,service=state.business.services.find(s=>s.id===$("service").value);if(!barber||!date||!service){$("slots").innerHTML="";$("slot-help").textContent="Selecione serviço, profissional e data.";return}$("slot-help").textContent="Carregando horários...";try{const data=await request(`/public/businesses/${businessId}/barbers/${barber}/availability?appointment_date=${date}`);const duration=service.duration_minutes*60000;const available=data.slots.filter(slot=>new Date(slot.starts_at).getTime()>Date.now());state.slots=available.filter(slot=>{const start=new Date(slot.starts_at).getTime(),target=start+duration;let cursor=start;for(const candidate of available){if(new Date(candidate.starts_at).getTime()===cursor)cursor=new Date(candidate.ends_at).getTime();if(cursor>=target)return true}return false});renderSlots()}catch(error){$("slot-help").textContent=error.message;$("slots").innerHTML=""}}
function updateSummary(){const service=state.business?.services.find(s=>s.id===$("service").value),barber=state.business?.barbers.find(b=>b.id===$("barber").value);$("summary-service").textContent=service?.name||"Escolha um serviço";$("summary-barber").textContent=barber?.full_name||"Escolha um profissional";$("summary-price").textContent=service?money(service.price_cents):"—";$("summary-duration").textContent=service?`${service.duration_minutes} min de atendimento`:"Duração a definir";$("summary-when").textContent=state.selected?`${new Date(state.selected.starts_at).toLocaleDateString("pt-BR",{day:"2-digit",month:"long",timeZone:state.business.timezone})} às ${time(state.selected.starts_at)}`:"Selecione um horário";$("summary-hint").textContent=state.selected?(rescheduleToken?"Confira e confirme seu novo horário.":"Preencha seus dados e confirme a reserva."):"Selecione um horário para continuar.";const step=state.selected?2:service&&barber?1:0;document.querySelectorAll(".steps li").forEach((item,index)=>{item.classList.toggle("active",index===step);item.classList.toggle("complete",index<step);if(index===step)item.setAttribute("aria-current","step");else item.removeAttribute("aria-current")})}
function renderSlots(){updateSummary();$("slot-help").textContent=state.slots.length?"Clique em um horário para selecionar.":"Nenhum horário disponível nesta data.";$("slots").innerHTML=state.slots.map((slot,index)=>`<button type="button" class="slot${state.selected?.starts_at===slot.starts_at?" selected":""}" aria-pressed="${state.selected?.starts_at===slot.starts_at}" data-index="${index}">${time(slot.starts_at)}</button>`).join("")}
function pruneExpiredSlots(){const upcoming=state.slots.filter(slot=>new Date(slot.starts_at).getTime()>Date.now());if(upcoming.length===state.slots.length)return;state.slots=upcoming;if(state.selected&&new Date(state.selected.starts_at).getTime()<=Date.now()){state.selected=null;$("submit").disabled=true;$("error").textContent="O horário escolhido já passou. Selecione outro horário."}renderSlots()}
setInterval(pruneExpiredSlots,15000);window.addEventListener("focus",pruneExpiredSlots);document.addEventListener("visibilitychange",()=>{if(!document.hidden)pruneExpiredSlots()});
$("slots").addEventListener("click",event=>{const button=event.target.closest("[data-index]");if(!button)return;document.querySelectorAll(".slot").forEach(item=>{item.classList.remove("selected");item.setAttribute("aria-pressed","false")});button.classList.add("selected");button.setAttribute("aria-pressed","true");state.selected=state.slots[Number(button.dataset.index)];$("submit").disabled=false;$("error").textContent="";updateSummary()});
[$("service"),$("barber"),$("date")].forEach(input=>input.addEventListener("change",loadSlots));
$("booking-form").addEventListener("submit",async event=>{event.preventDefault();pruneExpiredSlots();if(!state.selected)return;$("error").textContent="";$("submit").disabled=true;$("submit").firstElementChild.textContent="Confirmando...";try{const basePayload={barber_id:$("barber").value,service_id:$("service").value,starts_at:state.selected.starts_at};const result=rescheduleToken?await request(`/public/businesses/appointments/${rescheduleToken}/reschedule`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(basePayload)}):await request(`/public/businesses/${businessId}/appointments`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...basePayload,customer_name:$("name").value.trim(),customer_phone:$("phone").value.trim(),notes:$("notes").value.trim()||null})});$("booking-card").hidden=true;$("success-detail").textContent=`${result.service_name} com ${result.barber_name}, em ${new Date(result.starts_at).toLocaleDateString("pt-BR",{timeZone:state.business.timezone})} às ${time(result.starts_at)}.`;$("cancellation-link").value=`${location.origin}/dashboard/booking/?booking_token=${rescheduleToken||result.booking_token}`;state.latestToken=rescheduleToken||result.booking_token;const remembered=rememberBooking(state.latestToken,{...result,business_id:businessId,status:result.status||result.appointment?.status||"scheduled"});$("saved-notice").textContent=remembered?"Pronto! Ao voltar a esta página neste navegador, sua reserva estará em Meus agendamentos.":"Este navegador não permitiu salvar o acesso. Você pode gerenciar a reserva agora ou copiar o acesso abaixo para voltar depois.";$("backup-link").open=!remembered;$("saved-bookings").hidden=true;$("success").hidden=false;$("success").querySelector("h2").textContent=rescheduleToken?"Novo horário confirmado!":"Seu horário está reservado!";scrollTo({top:0,behavior:"smooth"})}catch(error){$("error").textContent=error.message;await loadSlots()}finally{$("submit").firstElementChild.textContent=rescheduleToken?"Confirmar novo horário":"Confirmar agendamento"}});
async function loadManagedBooking(){try{state.managed=await request(`/public/businesses/appointments/${bookingToken}`);$("business-name").textContent=state.managed.business_name;$("booking-card").hidden=true;$("success").hidden=true;$("saved-bookings").hidden=true;$("manage").hidden=false;renderManagedBooking()}catch(error){showPageError(error.message)}}
function renderManagedBooking(){rememberBooking(bookingToken,state.managed);$("manage-status").textContent=state.managed.status==="scheduled"?"Sua reserva foi realizada. Você pode confirmar sua presença aqui mesmo.":state.managed.status==="confirmed"?"Tudo certo! Sua presença já está confirmada.":"";const active=["scheduled","confirmed"].includes(state.managed.status);$("manage-icon").textContent=active?"✓":"×";$("manage-title").textContent=state.managed.status==="scheduled"?"Confirme sua presença":state.managed.status==="confirmed"?"Presença confirmada":"Agendamento cancelado";$("manage-detail").textContent=`${state.managed.service_name} com ${state.managed.barber_name}, em ${new Date(state.managed.starts_at).toLocaleDateString("pt-BR")} às ${new Date(state.managed.starts_at).toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}.`;$("reschedule-booking").hidden=!active;$("confirm-booking").hidden=state.managed.status!=="scheduled";$("cancel-booking").hidden=!active;$("cancel-booking").disabled=false}
$("copy-cancellation-link").addEventListener("click",async()=>{await navigator.clipboard.writeText($("cancellation-link").value);$("copy-cancellation-link").textContent="Link copiado!"});
$("cancel-booking").addEventListener("click",async()=>{if(!await confirmBookingCancellation())return;$("cancel-booking").disabled=true;try{state.managed=await request(`/public/businesses/appointments/${bookingToken}/cancel`,{method:"PATCH"});renderManagedBooking()}catch(error){showBookingNotice(error.message);$("cancel-booking").disabled=false}});
$("confirm-booking").addEventListener("click",async()=>{$("confirm-booking").disabled=true;try{state.managed=await request(`/public/businesses/appointments/${bookingToken}/confirm`,{method:"PATCH"});renderManagedBooking()}catch(error){showBookingNotice(error.message);$("confirm-booking").disabled=false}});
$("close-booking-confirmation").addEventListener("click",()=>closeBookingConfirmation(false));$("back-booking-confirmation").addEventListener("click",()=>closeBookingConfirmation(false));$("submit-booking-confirmation").addEventListener("click",()=>closeBookingConfirmation(true));$("booking-confirmation").addEventListener("click",event=>{if(event.target===$("booking-confirmation"))closeBookingConfirmation(false)});document.addEventListener("keydown",event=>{if(event.key==="Escape"&&!$("booking-confirmation").hidden)closeBookingConfirmation(false)});
$("reschedule-booking").addEventListener("click",()=>location.href=`${location.pathname}?business_id=${state.managed.business_id}&reschedule_token=${bookingToken}`);
function savedBusinessId(){return businessId||state.managed?.business_id||state.business?.id}
function savedKey(){return `osiris:bookings:${savedBusinessId()}`}
function readSavedBookings(){try{const entries=JSON.parse(localStorage.getItem(savedKey())||"[]");return Array.isArray(entries)?entries.filter(item=>item&&typeof item.token==="string"&&typeof item.starts_at==="string"&&Number.isFinite(Date.parse(item.starts_at))).slice(0,20):[]}catch{return []}}
function rememberBooking(token,booking){if(!token||!savedBusinessId())return false;try{const entries=readSavedBookings().filter(item=>item.token!==token);entries.unshift({token,starts_at:booking.starts_at,service_name:booking.service_name,barber_name:booking.barber_name,status:booking.status});localStorage.setItem(savedKey(),JSON.stringify(entries.slice(0,20)));return true}catch{return false}}
function renderSavedBookings(){const entries=readSavedBookings();$("saved-bookings").hidden=!entries.length;$("saved-booking-list").innerHTML=entries.map((entry,index)=>`<button type="button" class="saved-booking" data-saved-index="${index}"><span><strong>${escapeHtml(entry.service_name||"Sua reserva")}</strong><small>${escapeHtml(entry.barber_name||"")} · ${escapeHtml(new Date(entry.starts_at).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit",timeZone:state.business?.timezone||"America/Sao_Paulo"}))}</small></span><span>Ver reserva →</span></button>`).join("")}
function returnToBookings(){location.href=`${location.pathname}?business_id=${encodeURIComponent(savedBusinessId())}`}
$("view-booking").addEventListener("click",async()=>{bookingToken=state.latestToken;await loadManagedBooking();$("manage").scrollIntoView({behavior:"smooth",block:"start"})});
$("back-to-bookings").addEventListener("click",returnToBookings);
$("saved-booking-list").addEventListener("click",async event=>{const button=event.target.closest("[data-saved-index]");if(!button)return;const entry=readSavedBookings()[Number(button.dataset.savedIndex)];if(!entry)return;bookingToken=entry.token;await loadManagedBooking();$("manage").scrollIntoView({behavior:"smooth",block:"start"})});
$("forget-bookings").addEventListener("click",()=>{try{localStorage.removeItem(savedKey());renderSavedBookings();showBookingNotice("Acessos removidos deste navegador. As reservas continuam válidas.")}catch{showBookingNotice("Não foi possível remover os acessos salvos.")}});
$("new-booking").addEventListener("click",returnToBookings);boot();
